CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,role TEXT DEFAULT 'Reader');
CREATE TABLE ebooks(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,author TEXT,category TEXT,description TEXT,resource_url TEXT,access_level TEXT DEFAULT 'Open');
CREATE TABLE bookmarks(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,ebook_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,ebook_id));
